SELECT COALESCE(( SELECT CASE WHEN lo.level_cm = hi.level_cm THEN lo.volume_l ELSE lo.volume_l + ((CAST(? AS DOUBLE PRECISION) - lo.level_cm) / NULLIF(hi.level_cm - lo.level_cm, 0)) * (hi.volume_l - lo.volume_l) END FROM oc_calibration c JOIN LATERAL (SELECT level_cm, volume_l FROM oc_calibration_row r WHERE r.calibration_id=c.id AND r.level_cm <= CAST(? AS DOUBLE PRECISION) ORDER BY r.level_cm DESC LIMIT 1) lo ON TRUE JOIN LATERAL (SELECT level_cm, volume_l FROM oc_calibration_row r WHERE r.calibration_id=c.id AND r.level_cm >= CAST(? AS DOUBLE PRECISION) ORDER BY r.level_cm ASC LIMIT 1) hi ON TRUE WHERE c.tank_code = ? AND c.status = 'active' ORDER BY c.version_no DESC LIMIT 1), (SELECT (CAST(? AS DOUBLE PRECISION)/NULLIF(t.max_level_cm,0))*COALESCE(t.capacity_l, CASE WHEN t.tank_kind='RGS' THEN 8000 ELSE 50000 END) FROM oc_tank t WHERE t.tank_code=?)) AS volume_l
